const crypto = require('crypto');
const SECRET = $env.APPROVAL_SECRET;
if (!SECRET) throw new Error('APPROVAL_SECRET is not configured');

return $input.all().map(item => {
  const q = item.json.query ?? {};
  const sid    = String(q.sid ?? '');
  const exp    = Number(q.exp ?? 0);
  const sig    = String(q.sig ?? '');
  const action = String(q.action ?? '');

  const fail = (reason) => ({ json: { ok: false, reason, sid, action } });

  if (!sid || !exp || !sig)                 return fail('missing parameters');
  if (!['send', 'hold'].includes(action))   return fail('unknown action');

  const expected = crypto
    .createHmac('sha256', SECRET)
    .update(`${sid}.${exp}`)
    .digest('hex');

  let valid = false;
  try {
    valid = crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(sig));
  } catch { valid = false; }

  if (!valid)              return fail('invalid signature');
  if (Date.now() > exp)    return fail('link expired');

  return { json: { ok: true, sid, action, exp, sig } };
});

const v = $('Verify Token').first().json;
const rows = $input.all().filter(i => i.json.email);
const lead = rows[0]?.json ?? {};
const BASE = $env.N8N_PUBLIC_URL;

const esc = s => String(s ?? '')
  .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
  .replace(/"/g,'&quot;');

let inner;

if (!v.ok) {
  inner = `<h1 style="color:#b91c1c;margin:0 0 12px;font-size:20px">Link not valid</h1>
    <p style="margin:0;color:#374151">${v.reason === 'link expired'
      ? 'This approval link has expired. Open the lead in Slack for a fresh one.'
      : 'This link could not be verified.'}</p>`;
} else if (!lead.email) {
  inner = `<h1 style="color:#b91c1c;margin:0 0 12px;font-size:20px">Lead not found</h1>
    <p style="margin:0;color:#374151">No lead matches this link.</p>`;
} else if (lead.action_taken === 'email_sent') {
  inner = `<h1 style="color:#b45309;margin:0 0 12px;font-size:20px">Already sent</h1>
    <p style="margin:0;color:#374151">A reply was already sent to ${esc(lead.email)}.</p>`;
} else {
  const hidden = `
    <input type="hidden" name="sid" value="${esc(v.sid)}">
    <input type="hidden" name="exp" value="${esc(v.exp)}">
    <input type="hidden" name="sig" value="${esc(v.sig)}">`;

  inner = `
    <h1 style="margin:0 0 4px;font-size:20px;color:#111827">Send this reply?</h1>
    <p style="margin:0 0 20px;color:#6b7280;font-size:14px">
      To ${esc(lead.full_name)} &lt;${esc(lead.email)}&gt; · score ${esc(lead.icp_score)}/10
    </p>
    <div style="background:#f6f7f9;border-radius:8px;padding:16px;margin-bottom:24px;
                color:#374151;line-height:1.55;font-size:14px;white-space:pre-wrap">${esc(lead.personalized_opener)}</div>
    <div style="display:flex;gap:10px">
      <form method="POST" action="${BASE}/webhook/lead-approve" style="margin:0">
        ${hidden}<input type="hidden" name="action" value="send">
        <button type="submit" style="background:#15803d;color:#fff;border:0;border-radius:7px;
          padding:11px 20px;font-size:14px;font-weight:600;cursor:pointer">Send reply</button>
      </form>
      <form method="POST" action="${BASE}/webhook/lead-approve" style="margin:0">
        ${hidden}<input type="hidden" name="action" value="hold">
        <button type="submit" style="background:#fff;color:#374151;border:1px solid #d1d5db;
          border-radius:7px;padding:11px 20px;font-size:14px;cursor:pointer">Hold</button>
      </form>
    </div>`;
}

const html = `<!doctype html>
<html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow"><title>Approve reply</title></head>
<body style="font-family:system-ui,-apple-system,sans-serif;background:#f6f7f9;margin:0;padding:48px 16px">
  <div style="max-width:520px;margin:0 auto;background:#fff;border-radius:12px;padding:32px;
              box-shadow:0 1px 3px rgba(0,0,0,.08)">${inner}</div>
</body></html>`;

return [{ json: { html } }];
